import { useCopyToClipboard } from "@/registry/erbium/hooks/use-copy-to-clipboard";
import { Button } from "@/registry/erbium/ui/button";
export default function Demo() {
  const { copyToClipboard, isCopied } = useCopyToClipboard();
  return (
    <Button onClick={() => copyToClipboard("Erbium UI")}>
      {isCopied ? "Copied" : "Copy Erbium UI"}
    </Button>
  );
}

import Demo from "../examples/use-copy-to-clipboard-demo";

const Example = () => <Demo />;

export default Example;
